#!/usr/bin/env bash
# Loads the 7 consolidated services into ONE PostgreSQL database (default himsdev), one schema per service:
#   1. NN_<service>.sql           - creates schema <service> with its tables <old schema>_<table> (generated by tools/gen_database_v3.py)
#   2. seed/NN_<service>.seed.sql - minimal reference data so the workflow can run
# Order: identity first, then revenue & finance and operations & supply, then the rest.
# Safe to re-run: a service whose schema is already loaded is skipped.
#
# Server version of deploy.sh: connects to the HIMS database server 103.169.179.22:50085 as user hims by default
# (reachable from the office network / VPN only). The password is not stored here - pass it when running:
#   PGPASSWORD=... ./deploy_server.sh
#   DB_NAME=himsdev_test PGPASSWORD=... ./deploy_server.sh      # another database (default: himsdev)
#   PGHOST=... PGPORT=... PGUSER=... PGPASSWORD=... ./deploy_server.sh   # another server or login
# The login needs the right to create the database (CREATEDB) the first time, unless it already exists.
set -euo pipefail
cd "$(dirname "$0")"
export PGHOST="${PGHOST:-103.169.179.22}" PGPORT="${PGPORT:-50085}" PGUSER="${PGUSER:-hims}"
if [ -z "${PGPASSWORD:-}" ]; then echo "Set PGPASSWORD (password of $PGUSER on $PGHOST:$PGPORT), e.g. PGPASSWORD=... ./deploy_server.sh" >&2; exit 1; fi
DB_NAME="${DB_NAME:-himsdev}"
ORDER="01_identity_org 05_revenue_finance 06_operations_supply 02_patient_engagement 03_clinical_care 04_diagnostics 07_integration_comms"
if ! psql -d postgres -Atqc "select 1 from pg_database where datname='$DB_NAME'" | grep -q 1; then
  createdb -E UTF8 -T template0 "$DB_NAME"; echo "created database $DB_NAME"
fi
for name in $ORDER; do
  schema="${name#*_}"
  if [ "$(psql -d "$DB_NAME" -Atqc "select to_regclass('${schema}.evt_outbox') is not null" | tr -d '\r')" = "t" ]; then
    echo "[$DB_NAME.$schema] already loaded - skipping ${name}.sql"
  else
    echo "[$DB_NAME.$schema] applying ${name}.sql"; psql -v ON_ERROR_STOP=1 -q -d "$DB_NAME" -f "${name}.sql"
  fi
  [ -f "seed/${name}.seed.sql" ] && { echo "[$DB_NAME.$schema] applying seed"; psql -v ON_ERROR_STOP=1 -q -d "$DB_NAME" -f "seed/${name}.seed.sql" >/dev/null; }
done
# The services' login (user hims): only when its password is given, e.g. HIMS_DB_PASSWORD=... ./deploy_server.sh
# (not needed when this script itself runs as hims: the schemas are then owned by hims)
if [ -n "${HIMS_DB_PASSWORD:-}" ]; then
  echo "[$DB_NAME] login hims: grants on the service schemas"
  psql -v ON_ERROR_STOP=1 -q -d "$DB_NAME" -v hims_password="$HIMS_DB_PASSWORD" -f roles.sql >/dev/null
fi
echo "done."
